# cloud_audit_sdk.rb - Cloud Infrastructure Audit Logging SDK
require 'json'
require 'time'
require 'securerandom'

module CloudInfra
  module AuditLog
    class Formatter
      SEVERITY_LEVELS = { debug: 0, info: 1, warn: 2, error: 3, critical: 4 }.freeze

      def initialize(template: nil)
        @template = template || "[%{timestamp}] %{severity} | %{source} | %{message}"
      end

      def render(entry)
        interpolate(@template, entry)
      end

      private

      def interpolate(pattern, values)
        pattern % values
      end
    end

    class TransportBuffer
      def initialize(max_size: 1000)
        @buffer = []
        @max_size = max_size
        @mutex = Mutex.new
      end

      def push(entry)
        @mutex.synchronize do
          @buffer.shift if @buffer.size >= @max_size
          @buffer << entry
        end
      end

      def flush
        @mutex.synchronize do
          entries = @buffer.dup
          @buffer.clear
          entries
        end
      end
    end

    class AuditLogger
      attr_reader :source_id

      def initialize(source_id:, formatter: nil, transport: nil)
        @source_id = source_id
        @formatter = formatter || Formatter.new
        @transport = transport || TransportBuffer.new
        @enrichers = []
      end

      def add_enricher(enricher)
        @enrichers << enricher
      end

      def log_event(severity:, message:, metadata: {})
        entry = build_entry(severity, message, metadata)
        enriched = apply_enrichers(entry)
        formatted = @formatter.render(enriched)
        @transport.push({ raw: enriched, formatted: formatted })
        formatted
      end

      def log_api_call(method:, path:, user:, status:, duration_ms:)
        meta = { method: method, path: path, status: status, duration_ms: duration_ms }
        log_event(severity: :info, message: "API call by #{user}: #{method} #{path} -> #{status}", metadata: meta)
      end

      def log_resource_change(resource_type:, resource_id:, action:, actor:, details: "")
        msg = "Resource #{action}: #{resource_type}/#{resource_id} by #{actor}"
        msg += " (#{details})" unless details.empty?
        log_event(severity: :warn, message: msg, metadata: { resource_type: resource_type, resource_id: resource_id, action: action, actor: actor })
      end

      def log_security_event(event_type:, principal:, context: {})
        msg = build_security_message(event_type, principal, context)
        log_event(severity: :critical, message: msg, metadata: context.merge(event_type: event_type, principal: principal))
      end

      private

      def build_entry(severity, message, metadata)
        {
          timestamp: Time.now.utc.iso8601(3),
          severity: severity.to_s.upcase,
          source: @source_id,
          message: message,
          trace_id: SecureRandom.hex(8),
          metadata: metadata
        }
      end

      def apply_enrichers(entry)
        @enrichers.reduce(entry) { |e, enricher| enricher.call(e) }
      end

      def build_security_message(event_type, principal, context)
        base = "SECURITY[#{event_type}] principal=#{principal}"
        if context[:reason]
          base += " reason=#{context[:reason]}"
        end
        base
      end
    end

    class ComplianceReporter
      def initialize(logger:, report_template: nil)
        @logger = logger
        @report_template = report_template || "Compliance check %{check_id}: %{result} for %{scope}"
      end

      def report_check(check_id:, result:, scope:, user_note: "")
        entry = { check_id: check_id, result: result, scope: scope }
        formatted_report = render_report(entry, user_note)
        @logger.log_event(severity: :info, message: formatted_report, metadata: entry)
      end

      private

      def render_report(entry, user_note)
        base = @report_template % entry
        unless user_note.empty?
          base += " | Note: #{user_note}"
        end
        base
      end
    end
  end
end

